#include <assert.h>
#include <stdio.h>
#include "../native/engine.h"
int main(int argc,char**argv){assert(argc==2);tsf*base=load_font(argv[1]);assert(base);FX*f=calloc(1,sizeof(*f));config_fx(f,0,1,.8,0,120,4,.6);assert(scene_init(f));f->protect=1;f->tailScale=1;tsf*banks[4];float gain[4]={.5,.5,.5,.5},out[512];
 for(int ch=0;ch<4;ch++){banks[ch]=copy_font(base,256);assert(banks[ch]);tsf_channel_set_presetindex(banks[ch],0,0);pr_body_prepare(&f->parts[ch]->body,1,100,100,50,0,70,44100);f->parts[ch]->resonance=.2f;f->parts[ch]->mechanics.hammer=5;}
 scene_event(f,banks,(PrMidiEvent){0xB0,64,127,15});for(int note=48;note<84;note++)scene_event(f,banks,(PrMidiEvent){0x90,note,127,15});double energy=0;for(int n=0;n<200;n++){render_mixer_float(banks,f,gain,out,256);for(int i=0;i<512;i++){assert(isfinite(out[i])&&fabsf(out[i])<=.98001f);energy+=out[i]*out[i];}}assert(energy>1&&f->parts[0]->body.active);
 PrChannelFx*old=f->parts[0];scene_retire(f,banks[0],old,0,.5f);banks[0]=copy_font(base,256);assert(banks[0]);tsf_channel_set_presetindex(banks[0],0,4);f->parts[0]=part_new(44100);assert(f->tails[0].part==old&&old->body.enabled&&old->body.body==100&&!f->parts[0]->body.enabled);scene_event(f,banks,(PrMidiEvent){0x90,60,100,1});for(int n=0;n<50;n++){render_mixer_float(banks,f,gain,out,256);for(int i=0;i<512;i++)assert(isfinite(out[i])&&fabsf(out[i])<=.98001f);}part_rate(old,48000);assert(old->body.enabled&&old->body.body==100&&old->body.lid==70&&old->body.rate==48000);
 for(int note=48;note<84;note++)scene_event(f,banks,(PrMidiEvent){0x80,note,0,15});scene_event(f,banks,(PrMidiEvent){0xB0,64,0,15});for(int n=0;n<1200;n++)render_mixer_float(banks,f,gain,out,256);scene_all_silent(f);for(int ch=0;ch<4;ch++){assert(!f->parts[ch]->body.active);for(int i=0;i<16;i++)assert(f->parts[ch]->body.x[i]==0);tsf_close(banks[ch]);free(f->parts[ch]);}for(int n=0;n<PR_TAILS;n++){if(f->tails[n].bank)tsf_close(f->tails[n].bank);free(f->tails[n].part);}free(f);tsf_close(base);puts("PASS: 4-channel hot chords/pedal/protection, scene tail retains body settings while new scene is neutral, rate preserves controls, panic clears modes.");}
